mapper.select:
SELECT 
FROM HR_EMPLOYEE_RECRUIT A
WHERE A.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND A.ACTIVITY <> 2

  AND A.ACTIVITY = #{searchObject, jdbcType=VARCHAR}



      AND A.DATA_SOURCES = #{searchDataSources, jdbcType=VARCHAR}


      AND A.DATA_SOURCES IN ('1', '0')



  AND TO_DATE(A.DATE_STARTED, 'DD/MM/YYYY') >= TO_DATE(#{searchStartDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')


  AND TO_DATE(A.DATE_STARTED, 'DD/MM/YYYY') <= TO_DATE(#{searchEndDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')

ORDER BY A.CREATE_DATE DESC

SELECT 
FROM HR_EMPLOYEE_RECRUIT A
WHERE A.PERSON_ID = #{personId, jdbcType=VARCHAR}

mapper.update:
