    PHOTO_PATH  = #{photoPath, jdbcType=VARCHAR},
    UPDATE_DATE = SYSDATE,
    UPDATED_BY  = #{adminID, jdbcType=VARCHAR},
    UPDATED_IP  = #{adminIP, jdbcType=VARCHAR}
WHERE PERSON_ID = #{personId, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM HR_EMPLOYEE_RECRUIT
WHERE PERSON_ID = #{personId, jdbcType=VARCHAR}
  AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

