SELECT COUNT(1)
  FROM (SELECT 1
          FROM HR_EMPLOYEE
         WHERE EMPID = #{empId, jdbcType=VARCHAR}
           AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
        UNION ALL
        SELECT 1
          FROM HR_EMPLOYEE_RECRUIT
         WHERE EMPID = #{empId, jdbcType=VARCHAR}
           AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
           AND PERSON_ID <> NVL(#{personId, jdbcType=VARCHAR}, '000000000'))

